BEGIN READ ONLY;
SELECT n.nspname,c.relname,c.relrowsecurity,c.relforcerowsecurity FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('gaona_web_configuracion','gaona_web_registros','gaona_web_documentos','gaona_web_correos');
SELECT policyname,tablename,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname='public' AND policyname LIKE 'gaona_web_%';
SELECT n.nspname,p.proname,p.prosecdef,p.proconfig,pg_get_userbyid(p.proowner) AS propietario,pg_get_function_identity_arguments(p.oid),has_function_privilege('authenticated',p.oid,'EXECUTE') AS ejecutar,has_function_privilege('anon',p.oid,'EXECUTE') AS anon,has_function_privilege('service_role',p.oid,'EXECUTE') AS service_role FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE(n.nspname='public' AND p.proname='gaona_web_operacion') OR(n.nspname='gaona_web_interno' AND p.proname='operacion');
SELECT c.relname,co.conname,pg_get_constraintdef(co.oid) FROM pg_constraint co JOIN pg_class c ON c.oid=co.conrelid WHERE c.relname LIKE 'gaona_web_%' AND co.contype='f';
SELECT r.rolname,c.relname,has_any_column_privilege(r.oid,c.oid,'INSERT') AS insertar,has_any_column_privilege(r.oid,c.oid,'UPDATE') AS actualizar,has_any_column_privilege(r.oid,c.oid,'SELECT') AS leer,has_table_privilege(r.oid,c.oid,'TRUNCATE') AS truncar,has_table_privilege(r.oid,c.oid,'DELETE') AS borrar FROM pg_roles r CROSS JOIN pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname LIKE 'gaona_web_%' AND c.relkind='r' AND r.rolname IN ('anon','authenticated','service_role');
SELECT c.relname,c.relacl,c.relrowsecurity,c.relforcerowsecurity FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relname IN ('productos','categorias','clientes','solicitudes','solicitud_detalles');
SELECT n.nspname,has_schema_privilege('authenticated',n.oid,'CREATE') AS crear FROM pg_namespace n WHERE n.nspname='gaona_web_interno';
COMMIT;
